/* =====================================================================
   FS-08 (R8) seed data – Education Account service database. Built on the R4 FAS seed.
   Tables: dbo.Student_Profile, dbo.Wallets, dbo.Transactions. Generated 22/10/2026.

   Same students as R4 (same Id, Code, Nric, FullName, DateOfBirth, Citizenship) plus 6 added children
   (X01–X06, see R8_Seed_Data.xlsx). Run R4_addon.sql in the R4 database to add them there too.

   How to run:
     sqlcmd -S localhost,1433 -U sa -P "YourStrong@Password123" -C -d <EduAccountDatabase> -i R8_seed.sql
   Safe to run again: it deletes the seed rows (same Ids / NRICs) first, then inserts them.

   Parent_Profile is not seeded here. R4 already seeds 46 Parent_Profile rows (those parents are
   "returning" users). Parents without a profile log in for the first time (AC-1).

   Column matching: rows go to staging tables first; only columns that exist in the real table are copied.
   Transactions.Id is fixed (8,000,000 + TXN number) so the R9 seed can point to the same EA ledger rows.
   Money: Balance and Amount are BIGINT in the design, so the values are cents (SGD 12.50 = 1250).
   Citizenship uses the R4 values: Citizen, PR, Foreigner.
   X01 Hakim Karim turns 16 on the day you run this script (AC-7, AC-26).
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @Today date = CAST(GETDATE() AS date);
DECLARE @SeedUser varchar(50) = 'seed-r8';
IF OBJECT_ID('tempdb..#Student') IS NOT NULL DROP TABLE #Student;
IF OBJECT_ID('tempdb..#Wallet')  IS NOT NULL DROP TABLE #Wallet;
IF OBJECT_ID('tempdb..#Txn')     IS NOT NULL DROP TABLE #Txn;
CREATE TABLE #Student (Id uniqueidentifier, Code nvarchar(50), Nric varchar(9), FullName nvarchar(150), DateOfBirth date,
  Citizenship nvarchar(50), Status nvarchar(30), Gender nvarchar(10), Race nvarchar(50), Block nvarchar(20), Street nvarchar(100),
  Unit nvarchar(20), PostalCode varchar(10), Country nvarchar(100), FatherNric varchar(9), MotherNric varchar(9),
  SchoolId uniqueidentifier, School nvarchar(150), Level nvarchar(50), ClassName nvarchar(50),
  CreatedAt datetime2(3), UpdatedAt datetime2(3), CreatedBy varchar(50), UpdatedBy varchar(50));
CREATE TABLE #Wallet (Id uniqueidentifier, Code nvarchar(50), StudentId uniqueidentifier, Currency char(3), Balance bigint,
  Status nvarchar(30), StatusReason nvarchar(200), OpenedDate date, ScheduledClosureDate date, ActualClosureDate date,
  CreatedAt datetime2(3), UpdatedAt datetime2(3), CreatedBy varchar(50), UpdatedBy varchar(50));
CREATE TABLE #Txn (Id bigint, Code nvarchar(50), Reference nvarchar(50), WalletId uniqueidentifier, Type nvarchar(30), Direction nvarchar(10),
  Amount bigint, BalanceAfter bigint NULL, Status nvarchar(20), IsOnline bit, Description varchar(255),
  CreatedAt datetime2(3), UpdatedAt datetime2(3), CreatedBy varchar(50), UpdatedBy varchar(50));






DECLARE @sql nvarchar(max), @cols nvarchar(max), @t sysname, @s sysname;
BEGIN TRAN;
IF OBJECT_ID('dbo.Transactions') IS NOT NULL DELETE FROM dbo.Transactions WHERE WalletId IN (SELECT Id FROM #Wallet) OR Id IN (SELECT Id FROM #Txn);
IF OBJECT_ID('dbo.Wallets') IS NOT NULL DELETE FROM dbo.Wallets WHERE Id IN (SELECT Id FROM #Wallet) OR StudentId IN (SELECT Id FROM #Student);
IF OBJECT_ID('dbo.Student_Profile') IS NOT NULL DELETE FROM dbo.Student_Profile WHERE Id IN (SELECT Id FROM #Student) OR Nric IN (SELECT Nric FROM #Student);
DECLARE @map TABLE (Target sysname, Staging sysname, Ord int);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT Target, Staging FROM @map ORDER BY Ord;
OPEN c; FETCH NEXT FROM c INTO @t, @s;
WHILE @@FETCH_STATUS = 0
BEGIN
  IF OBJECT_ID('dbo.' + @t) IS NULL
  BEGIN RAISERROR('Target table dbo.%s not found. Run this script in the Education Account database.', 16, 1, @t); RETURN; END
  SELECT @cols = STRING_AGG(QUOTENAME(tc.name), ', ')
  FROM sys.columns tc JOIN tempdb.sys.columns sc ON sc.object_id = OBJECT_ID('tempdb..' + @s) AND sc.name = tc.name
  WHERE tc.object_id = OBJECT_ID('dbo.' + @t) AND tc.is_computed = 0 AND TYPE_NAME(tc.system_type_id) <> 'timestamp';
  PRINT 'dbo.' + @t + ' <- ' + @cols;
  PRINT '   skipped: ' + ISNULL((SELECT STRING_AGG(sc.name, ', ') FROM tempdb.sys.columns sc WHERE sc.object_id = OBJECT_ID('tempdb..' + @s)
          AND NOT EXISTS (SELECT 1 FROM sys.columns tc WHERE tc.object_id = OBJECT_ID('dbo.' + @t) AND tc.name = sc.name)), '(none)');
  SET @sql = N'INSERT INTO dbo.' + QUOTENAME(@t) + N' (' + @cols + N') SELECT ' + @cols + N' FROM ' + @s + N';';
  IF EXISTS (SELECT 1 FROM sys.columns tc JOIN tempdb.sys.columns sc ON sc.object_id = OBJECT_ID('tempdb..' + @s) AND sc.name = tc.name
             WHERE tc.object_id = OBJECT_ID('dbo.' + @t) AND tc.is_identity = 1)
    SET @sql = N'SET IDENTITY_INSERT dbo.' + QUOTENAME(@t) + N' ON; ' + @sql + N' SET IDENTITY_INSERT dbo.' + QUOTENAME(@t) + N' OFF;';
  EXEC sp_executesql @sql;
  FETCH NEXT FROM c INTO @t, @s;
END
CLOSE c; DEALLOCATE c;
COMMIT;

SELECT s.Code, s.FullName, s.DateOfBirth, s.Citizenship, w.Code AS EaCode, w.Status, w.Balance / 100.0 AS BalanceSGD,
       (SELECT COUNT(*) FROM dbo.Transactions t WHERE t.WalletId = w.Id) AS TxnCount
FROM #Student s LEFT JOIN #Wallet w ON w.StudentId = s.Id ORDER BY s.Code;